import{a as e,c as t,i as n,l as r,n as i,o as a,r as o,s,t as c}from"./app-FtcyK8lR.js";var l=JSON.parse(`{"path":"/api/runtime.html","title":"业务运行时 API","lang":"zh-CN","frontmatter":{},"git":{"updatedTime":1793083391000,"contributors":[{"name":"之旸 刘","username":"","email":"marufyurisa@outlook.com","commits":2}],"changelog":[{"hash":"a7bc7e5f74740c184e03fa5817e5e4576113490b","time":1793083391000,"email":"marufyurisa@outlook.com","author":"之旸 刘","message":"feat: integrate release workflows, managed backups and runtime fixes"},{"hash":"19811119f54f6a4d04aa76de9c6478413b9ca6ca","time":1792568191000,"email":"marufyurisa@outlook.com","author":"之旸 刘","message":"docs: rewrite fork API reference for published configurations and admin sessions"}]},"filePathRelative":"api/runtime.md"}`),u={name:`runtime.md`};function d(c,l,u,d,f,p){let m=t(`RouteLink`);return s(),o(`div`,null,[l[3]||=i(`h1`,{id:`业务运行时-api`,tabindex:`-1`},[i(`a`,{class:`header-anchor`,href:`#业务运行时-api`},`#`),e(` 业务运行时 API`)],-1),i(`p`,null,[a(m,{to:`/api/`},{default:r(()=>[...l[0]||=[e(`返回 API 入口`,-1)]]),_:1}),l[2]||=e(` · `,-1),a(m,{to:`/api/management.html`},{default:r(()=>[...l[1]||=[e(`管理员操作`,-1)]]),_:1})]),l[4]||=n(`<p>本文路径都相对于部署地址，例如 <code>http://127.0.0.1:18080/rainbow-bridge</code>。公开业务读取无需管理员登录。每次读取或导出都固定本次解析到的快照，不会把两个版本的配置混在一起。</p><h2 id="_1-读取当前生效版本" tabindex="-1"><a class="header-anchor" href="#_1-读取当前生效版本">#</a> 1. 读取当前生效版本</h2><div class="language-http line-numbers-mode" data-highlighter="prismjs" data-ext="http"><pre><code class="language-http"><span class="line">GET /api/v1/runtime/release</span>
<span class="line"><span class="token header"><span class="token header-name keyword">x-environment</span><span class="token punctuation">:</span> <span class="token header-value">default</span></span></span>
<span class="line"><span class="token header"><span class="token header-name keyword">x-pipeline</span><span class="token punctuation">:</span> <span class="token header-value">default</span></span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>未传 <code>version</code> 时读取该范围的生效指针。管理员切换后，下一次请求读取新版本；编辑区的增删改不会直接改变已发布版本。没有生效版本返回 404，不会自动读编辑区或最新创建的版本。</p><p>命令示例（Bash/curl；Windows 使用 curl.exe，按 shell 调整换行）：</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line"><span class="token function">curl</span> --fail-with-body <span class="token string">&#39;http://127.0.0.1:18080/rainbow-bridge/api/v1/runtime/release&#39;</span> <span class="token punctuation">\\</span></span>
<span class="line">  <span class="token parameter variable">-H</span> <span class="token string">&#39;x-environment: default&#39;</span> <span class="token punctuation">\\</span></span>
<span class="line">  <span class="token parameter variable">-H</span> <span class="token string">&#39;x-pipeline: default&#39;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>成功 HTTP 200，示例仅展示一个配置，ID、时间与摘要需使用实际响应：</p><div class="language-json line-numbers-mode" data-highlighter="prismjs" data-ext="json"><pre><code class="language-json"><span class="line"><span class="token punctuation">{</span></span>
<span class="line">  <span class="token property">&quot;code&quot;</span><span class="token operator">:</span> <span class="token number">200</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token property">&quot;msg&quot;</span><span class="token operator">:</span> <span class="token string">&quot;OK&quot;</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token property">&quot;data&quot;</span><span class="token operator">:</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token property">&quot;snapshot_id&quot;</span><span class="token operator">:</span> <span class="token string">&quot;31111111-2222-4333-8444-555555555555&quot;</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token property">&quot;version&quot;</span><span class="token operator">:</span> <span class="token string">&quot;v1.0&quot;</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token property">&quot;source_freeze_revision&quot;</span><span class="token operator">:</span> <span class="token string">&quot;3&quot;</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token property">&quot;payload_sha256&quot;</span><span class="token operator">:</span> <span class="token string">&quot;0123456789abcdef0123456789abcdef0123456789abcdef0123456789abcdef&quot;</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token property">&quot;selection_mode&quot;</span><span class="token operator">:</span> <span class="token string">&quot;active&quot;</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token property">&quot;active_revision&quot;</span><span class="token operator">:</span> <span class="token string">&quot;2&quot;</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token property">&quot;activated_at&quot;</span><span class="token operator">:</span> <span class="token string">&quot;2026-10-21T02:00:00Z&quot;</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token property">&quot;environment&quot;</span><span class="token operator">:</span> <span class="token punctuation">{</span></span>
<span class="line">      <span class="token property">&quot;environment_key&quot;</span><span class="token operator">:</span> <span class="token string">&quot;default&quot;</span><span class="token punctuation">,</span></span>
<span class="line">      <span class="token property">&quot;environment_name&quot;</span><span class="token operator">:</span> <span class="token string">&quot;默认环境&quot;</span><span class="token punctuation">,</span></span>
<span class="line">      <span class="token property">&quot;pipeline_key&quot;</span><span class="token operator">:</span> <span class="token string">&quot;default&quot;</span><span class="token punctuation">,</span></span>
<span class="line">      <span class="token property">&quot;pipeline_name&quot;</span><span class="token operator">:</span> <span class="token string">&quot;默认渠道&quot;</span></span>
<span class="line">    <span class="token punctuation">}</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token property">&quot;configs&quot;</span><span class="token operator">:</span> <span class="token punctuation">[</span></span>
<span class="line">      <span class="token punctuation">{</span></span>
<span class="line">        <span class="token property">&quot;resource_key&quot;</span><span class="token operator">:</span> <span class="token string">&quot;demo-key&quot;</span><span class="token punctuation">,</span></span>
<span class="line">        <span class="token property">&quot;alias&quot;</span><span class="token operator">:</span> <span class="token string">&quot;welcome&quot;</span><span class="token punctuation">,</span></span>
<span class="line">        <span class="token property">&quot;name&quot;</span><span class="token operator">:</span> <span class="token string">&quot;欢迎语&quot;</span><span class="token punctuation">,</span></span>
<span class="line">        <span class="token property">&quot;type&quot;</span><span class="token operator">:</span> <span class="token string">&quot;text&quot;</span><span class="token punctuation">,</span></span>
<span class="line">        <span class="token property">&quot;content&quot;</span><span class="token operator">:</span> <span class="token string">&quot;你好&quot;</span><span class="token punctuation">,</span></span>
<span class="line">        <span class="token property">&quot;remark&quot;</span><span class="token operator">:</span> <span class="token string">&quot;&quot;</span><span class="token punctuation">,</span></span>
<span class="line">        <span class="token property">&quot;is_perm&quot;</span><span class="token operator">:</span> <span class="token boolean">false</span><span class="token punctuation">,</span></span>
<span class="line">        <span class="token property">&quot;description&quot;</span><span class="token operator">:</span> <span class="token string">&quot;&quot;</span></span>
<span class="line">      <span class="token punctuation">}</span></span>
<span class="line">    <span class="token punctuation">]</span></span>
<span class="line">  <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><table><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td><code>snapshot_id</code></td><td>不可变快照 ID，可用于后续固定导出</td></tr><tr><td><code>version</code></td><td>当前环境/渠道内的发布版本名，字符串</td></tr><tr><td><code>source_freeze_revision</code></td><td>创建时的锁版 revision，十进制字符串</td></tr><tr><td><code>payload_sha256</code></td><td>快照 payload 摘要，不是整个 HTTP 响应的摘要</td></tr><tr><td><code>selection_mode</code></td><td>默认读取为 active，指定版本为 fixed</td></tr><tr><td><code>active_revision</code></td><td>生效指针 revision，十进制字符串；仅 active 模式出现</td></tr><tr><td><code>activated_at</code></td><td>本次读取指针对应的生效时间，RFC3339 UTC；fixed 模式省略，不是页面加载时间</td></tr><tr><td><code>configs</code></td><td>配置数组，无配置时为 <code>[]</code></td></tr></tbody></table><p>默认 <code>content_format=json</code>：object/keyvalue 的 content 返回原生 JSON 值；其他类型仍返回字符串，包括 number、boolean 类型。调用方按 <code>type</code> 使用，不应假定全部已自动转换成数字或布尔值。</p><h2 id="_2-固定读取指定版本" tabindex="-1"><a class="header-anchor" href="#_2-固定读取指定版本">#</a> 2. 固定读取指定版本</h2><div class="language-http line-numbers-mode" data-highlighter="prismjs" data-ext="http"><pre><code class="language-http"><span class="line">GET /api/v1/runtime/release?version=v1.0</span>
<span class="line"><span class="token header"><span class="token header-name keyword">x-environment</span><span class="token punctuation">:</span> <span class="token header-value">default</span></span></span>
<span class="line"><span class="token header"><span class="token header-name keyword">x-pipeline</span><span class="token punctuation">:</span> <span class="token header-value">default</span></span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>参数需 URL 编码。此时 <code>selection_mode</code> 为 fixed，不返回 <code>active_revision</code>、<code>activated_at</code>；其余结构同上。可读取已创建但当前未生效的版本；不依赖该范围是否已经设置 active。后续切换不会修改此版本的内容，但逻辑删除会使新请求返回 410。</p><p>不传 version 和 <code>?version=</code> 不同：后者明确提供了空版本号，返回 400。版本号仅在环境/渠道范围内解释，不是全局的虹桥程序版本。</p><h2 id="_3-原文模式与大整数" tabindex="-1"><a class="header-anchor" href="#_3-原文模式与大整数">#</a> 3. 原文模式与大整数</h2><div class="language-http line-numbers-mode" data-highlighter="prismjs" data-ext="http"><pre><code class="language-http"><span class="line">GET /api/v1/runtime/release?version=v1.0&amp;content_format=raw</span>
<span class="line"><span class="token header"><span class="token header-name keyword">x-environment</span><span class="token punctuation">:</span> <span class="token header-value">default</span></span></span>
<span class="line"><span class="token header"><span class="token header-name keyword">x-pipeline</span><span class="token punctuation">:</span> <span class="token header-value">default</span></span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><code>content_format</code> 可为 <code>json</code>（默认）或 <code>raw</code>；空值及其他值返回 400。raw 模式每个配置的 content 都是字符串，例如：</p><div class="language-json line-numbers-mode" data-highlighter="prismjs" data-ext="json"><pre><code class="language-json"><span class="line"><span class="token punctuation">{</span></span>
<span class="line">  <span class="token property">&quot;resource_key&quot;</span><span class="token operator">:</span> <span class="token string">&quot;big-number-key&quot;</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token property">&quot;alias&quot;</span><span class="token operator">:</span> <span class="token string">&quot;limits&quot;</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token property">&quot;name&quot;</span><span class="token operator">:</span> <span class="token string">&quot;额度&quot;</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token property">&quot;type&quot;</span><span class="token operator">:</span> <span class="token string">&quot;object&quot;</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token property">&quot;content&quot;</span><span class="token operator">:</span> <span class="token string">&quot;{\\&quot;big\\&quot;:9007199254740993}&quot;</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token property">&quot;remark&quot;</span><span class="token operator">:</span> <span class="token string">&quot;&quot;</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token property">&quot;is_perm&quot;</span><span class="token operator">:</span> <span class="token boolean">false</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token property">&quot;description&quot;</span><span class="token operator">:</span> <span class="token string">&quot;&quot;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>raw 保留配置内容中的数字文本；其中受管资源地址仍会按快照规则渲染，不意味着返回数据库里的逐字原始 payload。JavaScript 使用 <code>response.json()</code> 解析外层时，content 内的数字仍是字符串中的文本；之后若对 content 再用普通 <code>JSON.parse()</code>，超出安全整数范围的数字仍可能丢失精度。需要保持原文或自行使用无损解析方案。</p><h2 id="_4-固定导出版本资源包" tabindex="-1"><a class="header-anchor" href="#_4-固定导出版本资源包">#</a> 4. 固定导出版本资源包</h2><div class="language-http line-numbers-mode" data-highlighter="prismjs" data-ext="http"><pre><code class="language-http"><span class="line">GET /api/v1/runtime/release/static?version=v1.0&amp;expected_snapshot_id=31111111-2222-4333-8444-555555555555</span>
<span class="line"><span class="token header"><span class="token header-name keyword">x-environment</span><span class="token punctuation">:</span> <span class="token header-value">default</span></span></span>
<span class="line"><span class="token header"><span class="token header-name keyword">x-pipeline</span><span class="token punctuation">:</span> <span class="token header-value">default</span></span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>先读取版本，取得同一响应的 <code>data.version</code>、<code>data.snapshot_id</code>，再把它们传入本接口。<code>expected_snapshot_id</code> 是防止导出目标与已展示目标不一致的校验值，不是额外的访问密钥。两个参数及两个范围请求头均必填；ID 必须是 UUID，与定位的版本不一致返回 409。</p><p>成功返回 ZIP，错误返回 JSON。成功头包含：</p><div class="language-http line-numbers-mode" data-highlighter="prismjs" data-ext="http"><pre><code class="language-http"><span class="line"><span class="token header"><span class="token header-name keyword">Content-Type</span><span class="token punctuation">:</span> <span class="token header-value">application/zip</span></span></span>
<span class="line"><span class="token header"><span class="token header-name keyword">Content-Disposition</span><span class="token punctuation">:</span> <span class="token header-value">attachment; filename=...</span></span></span>
<span class="line"><span class="token header"><span class="token header-name keyword">Cache-Control</span><span class="token punctuation">:</span> <span class="token header-value">no-store</span></span></span>
<span class="line"><span class="token header"><span class="token header-name keyword">X-Rainbow-Snapshot-Id</span><span class="token punctuation">:</span> <span class="token header-value">31111111-2222-4333-8444-555555555555</span></span></span>
<span class="line"><span class="token header"><span class="token header-name keyword">X-Rainbow-Version</span><span class="token punctuation">:</span> <span class="token header-value">v1.0</span></span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>ZIP 内容：</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">config.json</span>
<span class="line">manifest.json</span>
<span class="line">assets/</span>
<span class="line">  &lt;asset_id&gt;.bin</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>config.json 包含版本元数据和 configs，资源地址替换为包内相对路径；manifest.json 包含格式标识、快照元数据和资源清单。每份资源包含大小、摘要及原始文件名等信息；<code>.bin</code> 是包内命名规则，不代表原始内容都是某种二进制格式。</p><p>这是配置与资源数据包，不含 index.html，不是可直接运行的网页，也不是 transfer 导入包或数据库备份。导出过程中切换 active 不影响已固定的导出目标。构包期限为 60 秒（调用方可更早取消），未压缩输出限额为 192 MiB；限额返回 413，超时返回 503，不返回伪装成功的错误 ZIP。</p><h2 id="_5-快照资源下载" tabindex="-1"><a class="header-anchor" href="#_5-快照资源下载">#</a> 5. 快照资源下载</h2><div class="language-http line-numbers-mode" data-highlighter="prismjs" data-ext="http"><pre><code class="language-http"><span class="line">GET /api/v1/release/asset/{snapshot_id}/{asset_id}</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>使用配置内容或版本详情实际返回的地址，不拼接原始编辑区路径。成功是原始文件字节和资源 Content-Type，服务端校验资源大小与 SHA-256。版本删除后新下载返回 410；资源缺失或完整性不符返回 503。业务读取本身检查引用文件存在和长度，资源下载时再核验完整 SHA-256。</p><h2 id="_6-旧接口迁移" tabindex="-1"><a class="header-anchor" href="#_6-旧接口迁移">#</a> 6. 旧接口迁移</h2><p>旧接口已经统一使用发布快照，<strong>不再读取编辑区</strong>。</p><table><thead><tr><th>接口</th><th>范围</th><th>行为</th></tr></thead><tbody><tr><td>GET <code>/api/v1/runtime/config</code></td><td>x-environment / x-pipeline 请求头，可选 query scope_id</td><td>当前生效快照；保留旧 config 字段并增加版本元数据</td></tr><tr><td>GET <code>/api/v1/runtime/static?environment_key=default&amp;pipeline_key=default</code></td><td>查询参数，可选 query scope_id</td><td>本次解析到的 active 资源包，不是固定某次之前展示的快照</td></tr><tr><td>GET <code>/api/v1/runtime/overview</code></td><td>无</td><td>环境/渠道列表，不能当成生效版本配置</td></tr></tbody></table><p>旧 config 的 data 为 snapshot_id、version、source_freeze_revision、active_revision、payload_sha256、selection_mode、environment、configs。每项 config 额外保留 environment_key、pipeline_key；object/keyvalue 返回 JSON，其余 content 为字符串。旧接口不提供 raw，也不承诺 activated_at。</p><p>旧 config/static 的 <code>scope_id</code> 现在真正生效：空串或 trim 后为空按当前有效范围读取；非空必须是 UUID 并校验为当前代。正确 pin 仍只跟随 active，切版后仍读新 active；它固定的是范围代身份，不是发布快照。非空非法 UUID 400 <code>SCOPE_INVALID_REQUEST</code>，从未存在 404 <code>SCOPE_NOT_FOUND</code>，不是当前代 409 <code>SCOPE_IDENTITY_CONFLICT</code>，已删除/同名重建后的旧 ID 410 <code>SCOPE_DELETED</code>。静态错误返回 JSON，不返回 ZIP 附件。</p><p>旧 config/static 明确传 <code>version</code>、<code>expected_snapshot_id</code> 或 <code>content_format</code> 仍返回 400，不能以为它们已支持新接口的版本选择参数。需要固定读取、raw 或固定导出时使用新接口。静态包格式也已改变，旧消费方应按 manifest 和相对资源路径适配。</p><h2 id="_7-错误与缓存" tabindex="-1"><a class="header-anchor" href="#_7-错误与缓存">#</a> 7. 错误与缓存</h2><p>运行时错误使用实际 HTTP 状态，示例：</p><div class="language-json line-numbers-mode" data-highlighter="prismjs" data-ext="json"><pre><code class="language-json"><span class="line"><span class="token punctuation">{</span></span>
<span class="line">  <span class="token property">&quot;code&quot;</span><span class="token operator">:</span> <span class="token number">404</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token property">&quot;msg&quot;</span><span class="token operator">:</span> <span class="token string">&quot;error&quot;</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token property">&quot;error&quot;</span><span class="token operator">:</span> <span class="token string">&quot;scope default/default has no active release&quot;</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token property">&quot;error_type&quot;</span><span class="token operator">:</span> <span class="token string">&quot;RELEASE_NOT_ACTIVE&quot;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><table><thead><tr><th>HTTP</th><th>error_type</th><th>调用方处理</th></tr></thead><tbody><tr><td>400</td><td>RELEASE_INVALID_REQUEST</td><td>补范围、合法 version/content_format 或有效 UUID</td></tr><tr><td>400</td><td>SCOPE_INVALID_REQUEST</td><td>旧 config/static 的 scope_id 不是 UUID</td></tr><tr><td>404</td><td>RELEASE_SCOPE_NOT_FOUND</td><td>核对环境和渠道</td></tr><tr><td>404</td><td>SCOPE_NOT_FOUND</td><td>旧接口指定的 scope_id 从未存在</td></tr><tr><td>409</td><td>SCOPE_IDENTITY_CONFLICT</td><td>scope_id 不是请求环境/渠道的当前代</td></tr><tr><td>410</td><td>SCOPE_DELETED</td><td>scope_id 已删除，包括同名重建后的旧代</td></tr><tr><td>404</td><td>API_NOT_FOUND</td><td>未知 API 路由；纯 API 和完整应用均为 JSON，不回退 SPA</td></tr><tr><td>404</td><td>RELEASE_NOT_ACTIVE</td><td>管理员尚未切换生效版本</td></tr><tr><td>404</td><td>RELEASE_VERSION_NOT_FOUND / RELEASE_ASSET_NOT_FOUND</td><td>核对版本或资源标识</td></tr><tr><td>409</td><td>RELEASE_SNAPSHOT_MISMATCH</td><td>固定导出目标与先前读取结果不符，核对范围和 ID</td></tr><tr><td>410</td><td>RELEASE_VERSION_DELETED</td><td>版本已删除，不能通过重试恢复</td></tr><tr><td>413</td><td>RELEASE_LIMIT_EXCEEDED</td><td>查看 limits，缩减导出内容或调整发布方案</td></tr><tr><td>503</td><td>RELEASE_INCOMPLETE</td><td>快照/清单/文件不完整，由管理员恢复，服务端不回退编辑区</td></tr><tr><td>503</td><td>RELEASE_EXPORT_TIMEOUT</td><td>导出超时；可在合适退避后重试同一固定目标</td></tr><tr><td>500</td><td>RELEASE_INTERNAL_ERROR / RELEASE_STORAGE_ERROR</td><td>检查服务端日志</td></tr></tbody></table><p>这些快照读取与导出使用 <code>Cache-Control: no-store</code>。跟随 active 的接入方不能无条件缓存五分钟后再称“实时切换”；如果自行设计缓存，应明确刷新周期及可接受的生效延迟。固定版本内容不可修改，但逻辑删除会阻止新的服务端读取；客户端已下载的副本无法被远程撤回。</p><p>重试仅用于网络故障和适当的临时服务错误，不能盲目重试 400/404/409/410。失败不应被客户端悄悄替换为编辑区配置。</p>`,43)])}var f=c(u,[[`render`,d]]);export{l as _pageData,f as default};